scripts.script:
if (args.isHit && args.isAttack && args.move && (args.move.type !== 'basic' || args.move.id === 'opportunity-attack')) {
    const msg = `
    <div class="xjzl-chat-card">
        <div style="padding:5px; padding-left: 8px; border-left:4px solid #d35400; background:rgba(211,84,0,0.1); margin-left: 2px;">
            <div style="font-weight:bold; color:#d35400; font-size:1.1em;">
                <i class="fas fa-bullhorn"></i> 兽吼功·震慑
            </div>
            <div style="font-size:0.9em; margin-top:5px; color:#555;">
                你可以消耗<b>反应动作</b>发出兽吼，使周围 3 米的敌人流失 <span style="font-weight:bold; color:red;">5</span> 点气血。<br>
                <i style="color:#888;">(请手动对范围内的敌人应用流失伤害)</i>
            </div>
        </div>
    </div>`;
    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: msg
    });
}

if (!game.combat) return;
if (args.move && (args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;

if (!actor.effects.some(e => e.getFlag('xjzl-system', 'slug') === 'neigong_fuqi_buff')) {
    let count = actor.getFlag('xjzl-system', 'neigong_fuqi_count') || 0;
    count++;
    if (count >= 3) {
        const eff = thisItem.effects.getName('伏气充盈(小成)');
        if (eff) {
            const data = eff.toObject();
            delete data._id;
            data.origin = thisItem.uuid;
            await game.xjzl.api.effects.addEffect(actor, data);
            actor.showFloatyText('伏气充盈', { fill: '#00ffff' });
        }
        count = 0;
    }
    await actor.setFlag('xjzl-system', 'neigong_fuqi_count', count);
}

if (!game.combat) return;
if (args.move && (args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;

if (!actor.effects.some(e => e.getFlag('xjzl-system', 'slug') === 'neigong_fuqi_buff')) {
    let count = actor.getFlag('xjzl-system', 'neigong_fuqi_count') || 0;
    count++;
    if (count >= 3) {
        const eff = thisItem.effects.getName('伏气充盈(圆满)');
        if (eff) {
            const data = eff.toObject();
            delete data._id;
            data.origin = thisItem.uuid;
            await game.xjzl.api.effects.addEffect(actor, data);
            actor.showFloatyText('伏气充盈', { fill: '#00ffff' });
        }
        count = 0;
    }
    await actor.setFlag('xjzl-system', 'neigong_fuqi_count', count);
}

if (S.resources.hp.value < (S.resources.hp.max * 0.3) && ["waigong", "neigong"].includes(args.type) && S.resources.mp.value > 0 && args.output.damage > 1) {
    const mp = S.resources.mp.value;
    const maxAbsorbable = Math.max(0, args.output.damage - 1);
    const maxMpCost = Math.min(mp, Math.ceil(maxAbsorbable / 3));

    if (maxMpCost > 0) {
        const content = `
        <div style="padding:5px;">
            <p style="color:#d35400; font-weight:bold;">气血极危，伏气护体触发！</p>
            <p>即将受到 <b>${args.output.damage}</b> 点伤害，当前内力: <b>${mp}</b>。</p>
            <p style="font-size:0.9em; color:#555;">每消耗 1 点内力可抵消 3 点伤害（至少受 1 点伤害）。</p>
            <hr>
            <div style="display:flex; align-items:center; justify-content:space-between;">
                <label><b>消耗内力:</b></label>
                <input type="number" id="fuqi-mp-cost" value="${maxMpCost}" min="0" max="${maxMpCost}" step="1" style="width:80px; text-align:center;">
            </div>
        </div>`;

        const confirm = await foundry.applications.api.DialogV2.prompt({
            window: { title: "伏气功 - 护体决断" },
            content: content,
            ok: {
                label: "确认消耗",
                callback: (event, button) => {
                    const input = button.form.elements["fuqi-mp-cost"];
                    return parseInt(input.value) || 0;
                }
            },
            rejectClose: false
        });

        if (confirm && confirm > 0) {
            const actualCost = Math.min(confirm, maxMpCost);
            const actualAbsorb = actualCost * 3;

            await actor.applyHealing({amount: -actualCost, type: 'mp', showScrolling: false});
            args.output.damage = Math.max(1, args.output.damage - actualAbsorb);

            actor.showFloatyText(`伏气 -${actualAbsorb}伤`, { fill: "#3498db" });
        }
    }
}

if (args.move && (args.move.type !== 'basic' || args.move.id === 'opportunity-attack')) {
    await actor.applyHealing({amount: 10, type: 'mp'});
    await thisEffect.delete();
}

if (args.move && (args.move.type !== 'basic' || args.move.id === 'opportunity-attack')) {
    await actor.applyHealing({amount: 20, type: 'mp'});
    await thisEffect.delete();
}

if (!args.attacker || args.attacker.uuid === actor.uuid) return;
if (args.baseDamage <= 200) return;
const markSlug = "fulong_mark_" + actor.id;
if (args.attacker.effects.some(e => e.getFlag("xjzl-system", "slug") === markSlug)) return;
const innerScript = "const originItem = await fromUuid(thisEffect.origin);\nconst wearer = originItem?.parent;\nif (wearer) {\n    await wearer.applyHealing({ amount: 10, type: 'hp', showScrolling: true });\n    const msg = '<div class=\"xjzl-chat-card\" style=\"margin-left: 6px;\"><div style=\"padding:5px; border-left: 4px solid #27ae60; background: rgba(39, 174, 96, 0.05);\"><div style=\"font-weight:bold; color:#27ae60;\"><i class=\"fas fa-heart\"></i> 伏龙诀 - 伤后回生</div><div style=\"font-size:0.9em; margin-top:4px;\"><b>' + actor.name + '</b> 的回合结束，<b>' + wearer.name + '</b> 回复了 <span style=\"color:green; font-weight:bold;\">10</span> 点气血。</div></div></div>';\n    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: wearer}), content: msg });\n}\nawait thisEffect.delete();";
const effectData = {
    name: "伏龙回生印记",
    icon: "systems/xjzl-system/assets/icons/neigong/万兽.png",
    description: "在你的回合结束时，将为 " + actor.name + " 回复气血。",
    flags: {
        "xjzl-system": {
            slug: markSlug,
            scripts: [
                {
                    trigger: "turnEnd",
                    label: "伏龙回血",
                    active: true,
                    script: innerScript
                }
            ]
        }
    },
    origin: thisItem.uuid,
    duration: { rounds: 1 }
};
await game.xjzl.api.effects.addEffect(args.attacker, effectData);
actor.showFloatyText("伏龙锁定！", { fill: "#27ae60" });

