if (args.baseDamage <= 100) return;
const markSlug = "fulong_mark_" + actor.id;
if (args.attacker.effects.some(e => e.getFlag("xjzl-system", "slug") === markSlug)) return;
const innerScript = "const originItem = await fromUuid(thisEffect.origin);\nconst wearer = originItem?.parent;\nif (wearer) {\n    await wearer.applyHealing({ amount: 20, type: 'hp', showScrolling: true });\n    const msg = '<div class=\"xjzl-chat-card\" style=\"margin-left: 6px;\"><div style=\"padding:5px; border-left: 4px solid #27ae60; background: rgba(39, 174, 96, 0.05);\"><div style=\"font-weight:bold; color:#27ae60;\"><i class=\"fas fa-heart\"></i> 伏龙诀 - 伤后回生</div><div style=\"font-size:0.9em; margin-top:4px;\"><b>' + actor.name + '</b> 的回合结束，<b>' + wearer.name + '</b> 回复了 <span style=\"color:green; font-weight:bold;\">20</span> 点气血。</div></div></div>';\n    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: wearer}), content: msg });\n}\nawait thisEffect.delete();";
const effectData = {
    name: "伏龙回生印记",
    icon: "systems/xjzl-system/assets/icons/neigong/万兽.png",
    description: "在你的回合结束时，将为 " + actor.name + " 回复气血。",
    flags: {
        "xjzl-system": {
            slug: markSlug,
            scripts: [
                {
                    trigger: "turnEnd",
                    label: "伏龙回血",
                    active: true,
                    script: innerScript
                }
            ]
        }
    },
    origin: thisItem.uuid,
    duration: { rounds: 1 }
};
await game.xjzl.api.effects.addEffect(args.attacker, effectData);
actor.showFloatyText("伏龙锁定！", { fill: "#27ae60" });

if (actor.system.resources.hp.value > 0) {
    const msg = "<div class='xjzl-chat-card' style='margin-left: 6px;'><div style='border-left: 3px solid #d35400; background: rgba(211, 84, 0, 0.1); padding: 5px 8px;'><div style='font-weight:bold; color:#c0392b;'><i class='fas fa-eye'></i> 伏龙诀 - 圆满威压</div><div style='font-size:0.9em; color:#555; margin-top:3px;'>进入战斗！请手动给 20 米内的所有敌人添加 <b>[伏龙威压]</b> 状态。</div></div></div>";
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
}
